"""Stage 92: the architecture chapter of the ORIGINAL (docs/58, generated by tools/analyze_original_architecture.py) is current, the facts it states are recomputed from the ROM and hold, and every chapter it points to exists."""
import glob
import os
import re
import sys
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, "tools"))
import analyze_original_architecture as AO  # noqa: E402
import output_map as O  # noqa: E402

DOC = os.path.join(ROOT, "docs", "58-original-architecture.md")


class Architecture(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.f = AO.facts()

    def test_the_chapter_is_current(self):
        with open(DOC, encoding="utf-8", newline="") as fh:
            have = fh.read().replace("\r\n", "\n")
        self.assertEqual(have, AO.doc(), "regenerate: python -I tools/analyze_original_architecture.py --doc docs/58-original-architecture.md")

    def test_the_headline_facts(self):
        f = self.f
        self.assertEqual((f["ins"], f["code"], f["data"], f["rom_size"]), (2925, 5946, 2246, 8192))
        self.assertEqual(f["routines"], 81)
        self.assertEqual((f["jsr"], f["indirect_jumps"], f["brk"]), (124, 0, 0))
        self.assertEqual(f["stack_ops"]["pha"] + f["stack_ops"]["php"], 8)
        self.assertEqual(f["stack_ops"]["pla"] + f["stack_ops"]["plp"], 8)
        self.assertEqual(f["outside_targets"], [0xE45C, 0xE462], "the only code outside the cartridge that is called is SETVBV and XITVBV")
        self.assertEqual(f["vectors"][:2], [0x86, 0xA3], "RUN = $A386")

    def test_the_subsystems_cover_all_the_code_and_all_the_routines(self):
        f = self.f
        self.assertEqual(sum(v[2] for v in f["subsystems"].values()), f["routines"])
        self.assertEqual(sum(v[3] for v in f["subsystems"].values()), f["code"])

    def test_the_five_contexts(self):
        self.assertEqual(set(self.f["contexts"]), {"key", "newgame", "vbi", "dli1", "dli2"})

    def test_every_memory_region_of_the_output_chapter_is_in_the_table(self):
        with open(DOC, encoding="utf-8") as fh:
            t = fh.read()
        for name, lo, hi, kind in O.REGIONS:
            self.assertIn("`$%04X-$%04X` | %s |" % (lo, hi, name), t, name)
            self.assertIn(name, AO.REGION_TEXT, name)

    def test_every_chapter_it_points_to_exists(self):
        with open(DOC, encoding="utf-8") as fh:
            t = fh.read()
        nums = set(re.findall(r"`(\d\d)`", t)) | {n.strip() for _, c in AO.CHAPTERS for n in c.split(",")}
        self.assertGreater(len(nums), 30)
        for n in sorted(nums):
            self.assertTrue(glob.glob(os.path.join(ROOT, "docs", n + "-*.md")), "no chapter " + n)


if __name__ == "__main__":
    unittest.main()
